require_once __DIR__.'/../backend/db.php';require_once __DIR__.'/../backend/helpers.php';require_once __DIR__.'/../backend/csrf.php';if(APP_ENV==='production'){http_response_code(404);exit;}$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($pw)>=10&&preg_match('/[A-Z]/',$pw)&&preg_match('/[a-z]/',$pw)&&preg_match('/[0-9]/',$pw)&&preg_match('/[^A-Za-z0-9]/',$pw)){$hash=password_hash($pw,PASSWORD_DEFAULT);$role='super_admin';$status='active';$s=$conn->prepare('INSERT INTO users(full_name,email,password_hash,role,account_status,email_verified_at) VALUES (?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),password_hash=VALUES(password_hash),role=VALUES(role),account_status="active",email_verified_at=COALESCE(email_verified_at,NOW())');$s->bind_param('sssss',$name,$email,$hash,$role,$status);$s->execute();$id=$conn->insert_id?:($conn->query("SELECT id FROM users WHERE email='".$conn->real_escape_string($email)."'")->fetch_assoc()['id']??0);if($id){$i=$conn->prepare("INSERT IGNORE INTO auth_identities(user_id,provider,provider_user_id) VALUES (?,'password',?)");$i->bind_param('is',$id,$email);$i->execute();}$message='Owner account created/updated. Delete this tools folder before production.';}else{$message='Use a valid email and a strong 10+ character password.';}}
